__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"deletionIntroEn",{enumerable:!0,get:function(){return t}}),e.deletionSectionsEn=function(t){return[{title:'Option 1: In the app (fastest)',blocks:[{items:['Open the app and go to Settings \u2192 Account.',"Tap Delete account. Once you confirm, it's deleted right away."],numbered:!0},{text:'This works for anonymous accounts too.'}]},{title:'Option 2: On the website',blocks:[{items:['Open Settings on this website and sign in with the Google account you use in the app.',"Under Account, tap Delete account. Once you confirm, it's deleted right away."],numbered:!0},{text:"An anonymous account lives only on the phone or browser where you started it, so use option 1. If you no longer have that device, an anonymous account is deleted automatically after 180 days in a row without opening the app or the website."}]},...t?[{title:'Option 3: By email',blocks:[{text:`If you can no longer use the app (for example, you lost your phone or uninstalled the app), email ${t} with the subject "Delete account".`},{items:[['Signed in with Google',"Send it from that account's email address, so we can tell it's you."],['Anonymous','Include your account ID (shown in the app under Settings \u2192 Account).']]},{text:"We'll finish within 30 days and reply to let you know."}]}]:[],{title:'What is deleted',blocks:[{items:['Your account: its ID, and the email address and Google account ID from signing in with Google','All your trips and searches','Your price alert history','Your push tokens','Feedback you sent','Your flight status lookups (kept only an hour anyway)','Your calendar price lookups (kept only an hour anyway)','Your language, plan and when you last used the app','Connection details of signed-in devices (IP address and browser)']}]},{title:'What is kept',blocks:[{items:[['Daily encrypted backups, up to 30 days',"Used only to restore the system after a failure; after a restore, your data is deleted again."],["The account's random ID, when it was deleted, and your consent records, 2 years",'Used to delete your data again after a restore from backup, and to show which version of the policy you agreed to if there is a dispute. No email or anything else that could reach you.'],['Connection and sign-in logs, error reports, up to 90 days',"May include an email, IP address or account ID. Deleted automatically on our service providers' schedules; used for security and fixing bugs."],["Fare data that belongs to no one, up to 180 days","For example a route's lowest price on a given day. It isn't personal data; it's used to show price trends."]]}]},{title:'Your Google account',blocks:[{text:"Deleting your Flyawait account doesn't delete your Google account. To also remove Flyawait's access to sign in with Google, go to Security in your Google Account and remove it under third-party apps and services."}]},{title:t?'Contact us':'More details',blocks:[{text:t?`Questions? Email ${t}. For the full details, see the Privacy Policy.`:'For the full details, see the Privacy Policy (Settings \u2192 About).'}]}]};const t="This page explains how to delete your Flyawait account and data. Uninstalling the app doesn't delete your account; use one of the ways below."},1004,[]);